export type PulsightInternalCoreUsecasesBacktestBacktestRequest = {
    /**
     * LatencySlots is the copy-fill landing latency in slots (blocks),
     * 0..MaxLatencySlots. 0 (default) keeps the zero-latency model: a copy
     * fills at the target's own post-swap price with slippage charged as a
     * flat haircut. 1..3 fills at the pool's EMPIRICAL resting price that many
     * slots after the target's swap, and the exec's slippage_bps becomes a
     * REVERT GATE instead of a charge — the fill is rejected (tip + priority
     * fee still paid) when the landing price drifted past the tolerance,
     * matching how the live executor's min_out floor behaves. Only copy-style
     * fills (Copy* and Target-signal-driven Emits) are affected; candle-driven
     * fills already price on the bucket close.
     */
    latency_slots?: number;
    /**
     * PerPool, when true, simulates each of a mint's significant markets as an
     * INDEPENDENT instrument — its own candle stream, indicators, ledger and
     * (for copy strategies) the target swaps on THAT pool — instead of a single
     * dominant/pinned pool per mint. Off ⇒ the historical one-position-per-mint
     * behaviour. Mutually exclusive with a SingleMint pool pin (a pin already
     * selects one market). Fans out compute by up to MaxPoolsPerMint per mint,
     * reflected in the tick-budget estimate.
     */
    per_pool?: boolean;
    scope?: PulsightInternalCoreUsecasesBacktestTokenScope;
    starting_balance_sol?: number;
    strategy_id?: string;
    time_range?: PulsightInternalCoreUsecasesBacktestTimeRange;
    timeframe?: PulsightInternalCoreDomainAggregatorTimeframe;
    /**
     * Venue selects the trading venue / chain for the run. Empty ⇒ solana
     * (back-compat). The runner gates chain-specific strategy nodes against
     * the venue's capabilities via StrategyDef.ValidateForVenue.
     */
    venue?: PulsightInternalCoreDomainStrategyVenueId;
};

export type PulsightInternalCoreUsecasesBacktestBacktestStatus = 'pending' | 'running' | 'done' | 'failed' | 'cancelled';

export type PulsightInternalCoreUsecasesBacktestBacktestSummary = {
    /**
     * AvgLandingDriftBps is the mean ADVERSE-signed drift (bps) actually
     * crossed by the run's FILLED copies — what latency cost on the fills that
     * went through (reverted ones are excluded; their cost shows as
     * RevertFeesSol + missed entries). Nil when the run had no landing fills.
     */
    avg_landing_drift_bps?: number;
    /**
     * CopiesDeclined counts target swaps a signal-driven exec wanted to act
     * on but that a RULE refused: cooldown, sizing, max_buys_per_open_position,
     * exposure cap, bracket placement, rate limit — plus the sells this run sat
     * out because the target only sold tokens it had never mirrored. Reverts
     * and unpriced skips have their own counters and are not in here. Every
     * one is persisted as a `backtest_declines` row with its reason, so the
     * trade history reads as a complete account of the target's swaps.
     * Additive JSONB field — old rows decode as 0.
     */
    copies_declined?: number;
    /**
     * CopiesReverted counts copy fills the slippage gate REJECTED: the pool's
     * landing price had drifted past the exec's slippage_bps between the
     * target's swap and our simulated landing. Unlike CopiesSkippedUnpriced
     * this is an EXECUTION OUTCOME, not a coverage gap — the data was fine,
     * the market moved, and a live bot's tx would have landed and reverted.
     * Each revert still pays its tip + priority fee (folded into
     * FeesPaidSol/TipsPaidSol and broken out in RevertFeesSol). Only possible
     * on latency_slots > 0 runs. Additive JSONB field — old rows decode as 0.
     */
    copies_reverted?: number;
    /**
     * CopiesSkippedUnpriced counts mirror trades that passed every rule and
     * would have fired, but whose triggering swap could not be priced honestly
     * — so they were NOT traded. Two causes, both data-side:
     *
     * 1. no post-swap price on the leg at all (every Meteora DLMM leg, and
     * every DAMM v2 / DBC leg ingested before those decoders were fixed);
     * 2. a leg whose reserve is impossible for a post-swap snapshot, which
     * means it is a PRE-swap one and its price is the pre-swap price
     * (PumpSwap — see postSwapReserveConsistent).
     *
     * A non-zero value means the run under-represents the strategy: it is a
     * COVERAGE gap, not a signal quality one. Cause 1 makes a launch-sniping
     * mirror over historical data skip most of its entries; cause 2 fires on
     * exactly the large launch buys such a strategy targets. Surfaced so a
     * mostly-skipped run reads as "not enough data" instead of quietly looking
     * like a thin strategy — or worse, than being filled at a fictional price
     * and looking profitable. Additive JSONB field — old rows decode as 0.
     */
    copies_skipped_unpriced?: number;
    ending_balance_sol?: number;
    fees_paid_sol?: number;
    /**
     * HeldPositions is every mint still open at run end — the bags the
     * strategy never sold, valued at their liquidity-aware exit (see
     * BacktestPosition). Their UnrealizedPnlSol sums into UnrealizedPnlSol
     * above. Empty when the strategy closed everything (all "Sold all").
     * Additive JSONB field — pre-existing rows decode as nil.
     */
    held_positions?: Array<PulsightInternalCoreUsecasesBacktestBacktestPosition>;
    /**
     * LandingContestedPct is the share (0-100) of filled copies whose pool saw
     * at least one other tx inside the latency gap — how often somebody beat
     * the bot to the pool. Nil when the run had no landing fills.
     */
    landing_contested_pct?: number;
    /**
     * LatencySlots echoes the run's landing latency (req.LatencySlots) so a
     * result is readable as which fill model produced it. 0 ⇒ the zero-latency
     * model. Additive JSONB field — old rows decode as 0, which is what they
     * ran. When > 0, the four fields below describe the landing plane.
     */
    latency_slots?: number;
    losses?: number;
    max_drawdown_sol?: number;
    /**
     * Price-impact rollups, in percent of mid. "Our*" averages over every
     * simulated trade that had a pool snapshot; "Target*" averages over the
     * copy trades that mirrored a target swap 1:1 (same timestamp). Zero when
     * no trade contributed (e.g. an indicator-only strategy, or a run with no
     * pool data). Additive JSONB fields — pre-existing rows decode as 0.
     */
    our_avg_price_impact_pct?: number;
    our_median_price_impact_pct?: number;
    /**
     * PerPool records whether the run simulated each market as an INDEPENDENT
     * instrument (req.PerPool). It is persisted because it is the LEDGER
     * BOUNDARY, and a reader cannot recover it from the trades: per-pool
     * fidelity stamps every fill with the pool it priced against in EVERY mode,
     * so a token that graduates mid-window (bonding curve → PumpSwap) carries
     * two pools on ONE merged ledger and looks exactly like two independent
     * instruments. The result page's per-token rollup used to guess from that
     * stamp and split a graduating token in two — the buys on a row reading
     * 0.000, the realizing sells and all of the profit on another. Additive
     * JSONB field; pre-existing rows decode as false, which is what all but an
     * opt-in run was.
     */
    per_pool?: boolean;
    /**
     * PositionsOpenedUnmarked counts positions the run opened while it had NO
     * price to mark them with — so for as long as that lasted, every
     * price-based exit rule (take-profit, stop, trailing stop, max-drawdown)
     * evaluated as undefined and could not fire.
     *
     * It happens because a copy fills at the price the TARGET left behind, on
     * the pool THEY traded, while the position is marked against the run's own
     * candle stream. Normally those are the same market. They are not when the
     * fill lands somewhere the stream does not cover — a parallel venue, or a
     * market whose candles simply have not started yet.
     *
     * Like CopiesSkippedUnpriced this is a COVERAGE number, not a result: an
     * exit rule that could not be evaluated did not decline to fire, it never
     * ran, and the position rode on until something else closed it. A non-zero
     * value means the run UNDER-represents its own exit rules — read the ROI
     * with that in mind.
     *
     * Mid-window graduations used to dominate this and no longer do: the
     * candle stream now merges a token's whole migration lineage, so a
     * bonding-curve entry is marked from the moment it opens. Additive JSONB
     * field — old rows decode as 0.
     */
    positions_opened_unmarked?: number;
    realized_pnl_sol?: number;
    /**
     * RevertFeesSol is the tip + priority-fee total burned by CopiesReverted
     * fills — money spent on txs that opened or closed nothing. Already
     * included in FeesPaidSol/TipsPaidSol; broken out so the cost of a
     * too-tight slippage setting is visible on its own. NOT walked into
     * MaxDrawdownSol (the drawdown walk only sees trade rows) — a documented
     * approximation.
     */
    revert_fees_sol?: number;
    roi_pct?: number;
    /**
     * SimulationAssumptions is free-text notes about which real-world
     * cost components the simulator did NOT model (route hops, MEV,
     * partial fills, pre-trade gas estimation, etc.). Rendered
     * prominently on the result page so users don't read "won 4.2 SOL"
     * too literally.
     */
    simulation_assumptions?: Array<string>;
    starting_balance_sol?: number;
    target_avg_price_impact_pct?: number;
    target_median_price_impact_pct?: number;
    tips_paid_sol?: number;
    total_pnl_sol?: number;
    trades?: number;
    unrealized_pnl_sol?: number;
    wins?: number;
};

export type PulsightInternalCoreUsecasesBacktestBacktestTrade = {
    backtest_id?: string;
    fee_sol?: number;
    idx?: number;
    /**
     * LandingDriftBps is the ADVERSE-signed price drift this copy actually
     * crossed between the target's post-swap price and the landing price it
     * filled at, in basis points (positive = the gap cost you, for buys and
     * sells alike). Set only on fills of a latency_slots > 0 run; 0 means
     * nobody traded the pool inside the gap. Nil on zero-latency runs and
     * candle-driven fills.
     */
    landing_drift_bps?: number;
    mint?: string;
    /**
     * Pool is the AMM market this trade executed in. For a COPY trade it's the
     * pool the mirrored target actually swapped in (per-leg dex_swaps); for an
     * EMIT trade it's the run's pinned pool (SingleMint pin) or nil when the
     * run resolved the mint's dominant pool (whose identity isn't surfaced).
     */
    pool?: string;
    pool_sol_at_trigger?: number;
    /**
     * PriceImpactPct is OUR own price impact on this fill, as a percent of the
     * mid price (size / pool_sol, the constant-product average-fill premium).
     * Nil when the engine had no pool snapshot at the tick (impact unknown →
     * pricing degraded to slippage-only). A buy moves price up, a sell down;
     * the magnitude is recorded either way.
     */
    price_impact_pct?: number;
    price_per_token?: number;
    realized_pnl_sol?: number;
    side?: PulsightInternalCoreUsecasesBacktestSide;
    sol_amount?: number;
    source?: PulsightInternalCoreUsecasesBacktestTradeSource;
    /**
     * TargetPriceImpactPct is the MIRRORED trader's own price impact on the
     * swap we copied — set on copy trades triggered by a target swap, measured
     * against the reconstructed pre-swap reserve. It describes THEIR fill, so
     * it is reported the same under a landing-latency run; it is never folded
     * into our own price. Nil for candle-driven emit trades.
     */
    target_price_impact_pct?: number;
    tip_sol?: number;
    token_amount?: number;
    triggering_swap_sig?: string;
    ts?: string;
};

export type PulsightInternalCoreUsecasesBacktestDeclineReason = 'cooldown' | 'unpriced' | 'zero_size' | 'size_out_of_range' | 'max_buys_per_position' | 'exposure_cap' | 'no_bracket' | 'rate_limited' | 'reverted' | 'unmirrored';

export type PulsightInternalCoreUsecasesBacktestPreviewMarker = {
    pool_sol_at_trigger?: number;
    /**
     * Price is the pessimistic execution price (slippage applied) so
     * the marker lines up with what a real run would have recorded.
     */
    price?: number;
    side?: PulsightInternalCoreUsecasesBacktestSide;
    source?: PulsightInternalCoreUsecasesBacktestTradeSource;
    /**
     * TS is epoch seconds.
     */
    ts?: number;
};

export type PulsightInternalCoreUsecasesBacktestPreviewRequest = {
    def?: PulsightInternalCoreDomainStrategyStrategyDef;
    mint?: string;
    /**
     * Pool pins the preview to one market of the mint. Empty lets the
     * candle source resolve the dominant pool within the window.
     */
    pool?: string;
    time_range?: PulsightInternalCoreUsecasesBacktestTimeRange;
    timeframe?: PulsightInternalCoreDomainAggregatorTimeframe;
};

export type PulsightInternalCoreUsecasesBacktestPreviewResponse = {
    markers?: Array<PulsightInternalCoreUsecasesBacktestPreviewMarker>;
    simulation_assumptions?: Array<string>;
};

export type PulsightInternalCoreUsecasesBacktestSide = 'buy' | 'sell';

export type PulsightInternalCoreUsecasesBacktestTimeRange = {
    from?: string;
    to?: string;
};

export type PulsightInternalCoreUsecasesBacktestTokenScope = {
    kind?: PulsightInternalCoreUsecasesBacktestTokenScopeKind;
    /**
     * MaxMints — on a Strategy scope this is STAMPED BY THE RUNNER at submit
     * (from the def's Universe node / mirror default) so the tick-budget and
     * credit math have a mint bound; requests don't set it. Legacy kinds
     * carried it on the wire. (The other legacy payload fields — trader,
     * window, include/exclude filters — were dropped 2026-07-28 with the
     * standalone resolution path; unknown keys on old persisted rows are
     * ignored on decode, so tolerant reads are unaffected.)
     */
    max_mints?: number;
    /**
     * SingleMint
     */
    mint?: string;
    /**
     * Mints
     */
    mints?: Array<string>;
    /**
     * Pool optionally pins a SingleMint run to one specific market (the AMM
     * pool pubkey) of the mint. Empty ⇒ the candle source resolves the mint's
     * dominant pool within the replay window (the historical default). Only
     * valid on the SingleMint variant — a pool belongs to exactly one mint, so
     * it is meaningless on a multi-mint / dynamic scope. Mirrors the preview's
     * PreviewRequest.Pool so a pinned run replays the same market the builder
     * previewed.
     */
    pool?: string;
};

export type PulsightInternalCoreUsecasesBacktestTokenScopeKind = 'strategy' | 'single_mint' | 'mints' | 'mirrors_traded' | 'standalone' | 'trader_traded';

export type PulsightInternalCoreUsecasesBacktestTradeSource = 'copy_buy' | 'copy_sell' | 'emit_buy' | 'emit_sell' | 'scope_exit';

export type PulsightInternalCoreUsecasesTraderPnlSeriesPoint = {
    /**
     * ArbPnl is the day's arbitrage take-home (tx-grain). It is
     * ALREADY included in Profit and Net — exposed separately so the UI can
     * show the split. Arb round-trip rows book zero realized PnL upstream,
     * so the inclusion never double-counts.
     */
    arb_pnl?: number;
    arb_pnl_usd?: number;
    cashback?: number;
    cashback_usd?: number;
    day?: string;
    failed_cost?: number;
    failed_cost_usd?: number;
    failed_txs?: number;
    /**
     * Costs of the day (lamports): per-tx fees, tips, and failed-tx burn,
     * against what pump paid the wallet that day — cashback CLAIMED and
     * holder rewards RECEIVED, both cash basis — with `net = profit - fees
     * - tips - failed_cost + cashback + holder_rewards` (profit already
     * includes the arbitrage take-home). The charts plot NET as the headline
     * series; `profit` stays as the flat/gross component.
     */
    fees?: number;
    fees_usd?: number;
    holder_reward_payouts?: number;
    /**
     * HolderRewards is the day's holder-reward payouts valued in SOL, and
     * HolderRewardPayouts how many payouts there were. A payout in a quote
     * we cannot price in SOL adds nothing to the value but still counts, so
     * a day can carry payouts with zero lamports.
     */
    holder_rewards?: number;
    holder_rewards_usd?: number;
    net?: number;
    net_usd?: number;
    profit?: number;
    /**
     * The Usd twins are the same day's figures on the trades' USD stamps
     * (micro-USD).
     */
    profit_usd?: number;
    success_rate?: number;
    tips?: number;
    tips_usd?: number;
    /**
     * Txs is the day's landed transaction count; FailedTxs the failed-tx
     * ledger's failed swaps+arbs+other. SuccessRate divides the OBSERVED
     * landed count (the `observed_hours` only) by observed+failed — nil
     * when no hour of the day was observed, so unobserved history reads
     * "not measured" rather than a fake 100%.
     */
    txs?: number;
};

